using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.Json;
using AwesomeAssertions;
using Mdf4Net.Tests.Infrastructure;
using Xunit;

namespace Mdf4Net.Tests;

/// <summary>
/// Files written by asammdf, an independent implementation, with the values they hold
/// (Fixtures/asammdf, regenerated by eng/interop/make_fixtures.py). The CI interop job checks the
/// same in both directions against the pinned asammdf; these fixtures make the reader half of it
/// part of every test run. raw_virtual_group is laid out by hand (no writer produces a group
/// without record bytes) and checked against asammdf's reading of it when it is generated.
/// </summary>
public class AsammdfFixtureTests
{
    public static IEnumerable<object[]> Fixtures()
        => Directory.GetFiles(MdfTestFile.FixturePath("asammdf"), "*.mf4")
            .Select(Path.GetFileNameWithoutExtension)
            .OrderBy(name => name, StringComparer.Ordinal)
            .Select(name => new object[] { name! });

    [Theory]
    [MemberData(nameof(Fixtures))]
    public void Values_Match_What_Asammdf_Wrote(string fixture)
    {
        using Mdf4File file = Mdf4File.Open(MdfTestFile.FixturePath("asammdf", fixture + ".mf4"));
        if (fixture.StartsWith("asammdf_", StringComparison.Ordinal))
        {
            file.ProgramId.Should().StartWith("amdf");
        }

        List<Mdf4ChannelGroup> groups = file.ChannelGroups.Where(g => !g.IsVariableLengthSignalData).ToList();

        using JsonDocument expected = JsonDocument.Parse(File.ReadAllText(MdfTestFile.FixturePath("asammdf", fixture + ".json")));
        if (expected.RootElement.TryGetProperty("start", out JsonElement start))
        {
            // asammdf computes the stored nanoseconds through a double; near the year 2500 its
            // resolution is 2,048 ns, so the file holds the start time to within that, not exactly.
            // FromTicks, not FromMilliseconds: .NET Framework rounds the latter to whole milliseconds.
            DateTimeOffset declared = DateTimeOffset.Parse(start.GetString()!, System.Globalization.CultureInfo.InvariantCulture);
            file.StartTime.Should().BeCloseTo(declared, TimeSpan.FromTicks(40), $"{fixture} start time");
            file.StartTime.Offset.Should().Be(declared.Offset, $"{fixture} time zone offset");
        }

        int checkedChannels = 0;
        foreach (JsonElement channel in expected.RootElement.GetProperty("channels").EnumerateArray())
        {
            string name = channel.GetProperty("name").GetString()!;
            Mdf4ChannelGroup group = groups[channel.GetProperty("group").GetInt32()];
            Mdf4Channel actual = group.FindChannel(name) ?? throw new Xunit.Sdk.XunitException($"{fixture}: channel {name} missing");

            double[] timestamps = channel.GetProperty("timestamps").EnumerateArray().Select(t => t.GetDouble()).ToArray();
            group.ReadTimestamps().Should().Equal(timestamps, $"{fixture}/{name} time stamps");

            if (channel.GetProperty("unit").ValueKind == JsonValueKind.String)
            {
                actual.Unit.Should().Be(channel.GetProperty("unit").GetString());
            }

            object?[] values = actual.ReadValues();
            JsonElement[] wanted = channel.GetProperty("values").EnumerateArray().ToArray();
            values.Should().HaveCount(wanted.Length);
            for (int i = 0; i < wanted.Length; i++)
            {
                object? want = wanted[i].ValueKind switch
                {
                    JsonValueKind.String => wanted[i].GetString(),
                    JsonValueKind.Number => wanted[i].GetDouble(),

                    // JSON has no NaN or infinity; they travel as {"float": "NaN"}.
                    JsonValueKind.Object => double.Parse(wanted[i].GetProperty("float").GetString()!, System.Globalization.CultureInfo.InvariantCulture),
                    _ => throw new InvalidOperationException($"unexpected JSON {wanted[i]}"),
                };

                if (want is double nan && double.IsNaN(nan))
                {
                    values[i].Should().BeOfType<double>().Which.Should().Be(double.NaN, $"{fixture}/{name}[{i}]");
                }
                else if (want is double d)
                {
                    values[i].Should().BeOfType<double>().Which.Should().BeApproximately(d, Math.Abs(d) * 1e-12, $"{fixture}/{name}[{i}]");
                }
                else
                {
                    values[i].Should().Be(want, $"{fixture}/{name}[{i}]");
                }
            }

            checkedChannels++;
        }

        checkedChannels.Should().BeGreaterThan(0);
    }

    [Fact]
    public void The_Fixture_Set_Is_Present()
    {
        Fixtures().Should().HaveCountGreaterThanOrEqualTo(7, "eng/interop/make_fixtures.py writes seven files");
    }
}
